static int touch_probe_read(FAR struct i2c_master_s *i2c, uint8_t addr,
                            uint16_t reg, FAR uint8_t *buf, uint8_t len)
{
  uint8_t regbuf[2] =
    {
      reg >> 8, reg & 0xff
    };

  struct i2c_msg_s msgv[2] =
    {
      {
        .frequency = 100000, .addr = addr, .flags = 0,
        .buffer = regbuf, .length = sizeof(regbuf)
      },
      {
        .frequency = 100000, .addr = addr, .flags = I2C_M_READ,
        .buffer = buf, .length = len
      }
    };

  return I2C_TRANSFER(i2c, msgv, 2);
}

static int touch_probe_write(FAR struct i2c_master_s *i2c, uint8_t addr,
                             uint16_t reg, uint8_t val)
{
  uint8_t buf[3] =
    {
      reg >> 8, reg & 0xff, val
    };

  struct i2c_msg_s msg =
    {
      .frequency = 100000, .addr = addr, .flags = 0,
      .buffer = buf, .length = sizeof(buf)
    };

  return I2C_TRANSFER(i2c, &msg, 1);
}

static void touch_probe_phase(FAR struct i2c_master_s *i2c,
                              FAR const char *name)
{
  uint8_t buf[1];
  uint8_t last = 0xff;
  int i;
  int hits = 0;

  syslog(LOG_ERR, "TPHASE %s start (touch now)\n", name);
  for (i = 0; i < 30; i++)
    {
      if (touch_probe_read(i2c, 0x5d, 0x814e, buf, 1) < 0)
        {
          syslog(LOG_ERR, "TPHASE %s read error\n", name);
          return;
        }

      if (buf[0] != last)
        {
          syslog(LOG_ERR, "TPHASE %s t=%dms status=%02x\n",
                 name, i * 100, buf[0]);
          last = buf[0];
        }

      if (buf[0] != 0)
        {
          hits++;
          touch_probe_write(i2c, 0x5d, 0x814e, 0);
        }

      nxsig_usleep(100 * 1000);
    }

  syslog(LOG_ERR, "TPHASE %s done hits=%d\n", name, hits);
}

