int vsai_logicpi_a1_touch_register(FAR const char *devpath,
                                    FAR struct i2c_master_s *i2c)
{
  /* TEMP DIAGNOSTIC (revert before commit): bisect which driver step
   * (register / open+irq-enable / close) breaks raw I2C status polling.
   */

  uint8_t buf[1];
  int probe_fd;
  int ret;

  struct i2c_msg_s regmsg =
    {
      .frequency = 100000, .addr = 0x5d, .flags = 0,
      .buffer = (uint8_t [])
      {
        0x81, 0x4e
      },
      .length = 2
    };

  struct i2c_msg_s rdmsg =
    {
      .frequency = 100000, .addr = 0x5d, .flags = I2C_M_READ,
      .buffer = buf, .length = 1
    };

  struct i2c_msg_s clrmsg =
    {
      .frequency = 100000, .addr = 0x5d, .flags = 0,
      .buffer = (uint8_t [])
      {
        0x81, 0x4e, 0x00
      },
      .length = 3
    };

  iinfo("devpath=%s\n", devpath);

  /* Route I2C0 to GPIOA_0 (SDA) / GPIOA_1 (SCL), function 3 */

  ret = s6_gpioa_set_mux(0, 3);
  if (ret < 0)
    {
      ierr("SDA mux failed: %d\n", ret);
      return ret;
    }

  ret = s6_gpioa_set_mux(1, 3);
  if (ret < 0)
    {
      ierr("SCL mux failed: %d\n", ret);
      return ret;
    }

  gt911_reset();

  syslog(LOG_ERR, "TPHASE A: poll before register (touch for 16s)\n");

  /* Phase A: before gt9xx_register */

  for (int i = 0; i < 40; i++)
    {
      I2C_TRANSFER(i2c, &regmsg, 1);
      I2C_TRANSFER(i2c, &rdmsg, 1);
      if (buf[0] != 0)
        {
          syslog(LOG_ERR, "TPHASE A t=%dms status=%02x\n",
                 i * 100, buf[0]);
          I2C_TRANSFER(i2c, &clrmsg, 1);
        }

      nxsig_usleep(100 * 1000);
    }

  gt9xx_register(devpath, i2c, CTP_I2C_ADDR, &g_vsai_logicpi_a1_gt9xx);

  syslog(LOG_ERR, "TPHASE B: poll after register\n");

  /* Phase B: after register (irq attached but disabled) */

  for (int i = 0; i < 40; i++)
    {
      I2C_TRANSFER(i2c, &regmsg, 1);
      I2C_TRANSFER(i2c, &rdmsg, 1);
      if (buf[0] != 0)
        {
          syslog(LOG_ERR, "TPHASE B t=%dms status=%02x\n",
                 i * 100, buf[0]);
          I2C_TRANSFER(i2c, &clrmsg, 1);
        }

      nxsig_usleep(100 * 1000);
    }

  probe_fd = open(devpath, O_RDONLY);
  syslog(LOG_ERR, "TPHASE C: open fd=%d, poll after open+irq-enable\n",
         probe_fd);

  /* Phase C: after open (reset + probe + irq enabled) */

  for (int i = 0; i < 40; i++)
    {
      I2C_TRANSFER(i2c, &regmsg, 1);
      I2C_TRANSFER(i2c, &rdmsg, 1);
      if (buf[0] != 0)
        {
          syslog(LOG_ERR, "TPHASE C t=%dms status=%02x\n",
                 i * 100, buf[0]);
          I2C_TRANSFER(i2c, &clrmsg, 1);
        }

      nxsig_usleep(100 * 1000);
    }

  close(probe_fd);
  syslog(LOG_ERR, "TPHASE D: poll after close\n");

  /* Phase D: after close (irq disabled again) */

  for (int i = 0; i < 40; i++)
    {
      I2C_TRANSFER(i2c, &regmsg, 1);
      I2C_TRANSFER(i2c, &rdmsg, 1);
      if (buf[0] != 0)
        {
          syslog(LOG_ERR, "TPHASE D t=%dms status=%02x\n",
                 i * 100, buf[0]);
          I2C_TRANSFER(i2c, &clrmsg, 1);
        }

      nxsig_usleep(100 * 1000);
    }

  syslog(LOG_ERR, "TPHASE done\n");
  return OK;
}

