/****************************************************************************
 * app/touchtest/touchtest_main.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>

#include <lvgl/lvgl.h>

#include <nuttx/input/touchscreen.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TOUCHTEST_DEV     CONFIG_EXAMPLES_TOUCHTEST_DEVPATH
#define RELEASE_TIMEOUT_MS 100

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_fd = -1;
static lv_indev_state_t g_state = LV_INDEV_STATE_RELEASED;
static int32_t g_x;
static int32_t g_y;
static uint64_t g_last_press_ms;
static int g_move_events;
static int g_click_events;
static uint8_t g_last_flags;
static lv_obj_t *g_info_label;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint64_t touchtest_now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/* The stock gt9xx driver reports a DOWN sample for each new contact frame
 * and a synthesized UP on the next read, so a held finger alternates
 * DOWN/UP.  Reconstruct a steady contact by staying pressed while fresh
 * position samples keep arriving, and releasing only after a short idle
 * window.
 */

static void touchtest_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
{
  struct touch_sample_s sample;
  uint64_t now = touchtest_now_ms();
  ssize_t nread;

  nread = read(g_fd, &sample, sizeof(sample));
  if (nread == (ssize_t)sizeof(sample) && sample.npoints >= 1 &&
      (sample.point[0].flags & TOUCH_POS_VALID) != 0)
    {
      g_x = sample.point[0].x;
      g_y = sample.point[0].y;
      g_last_flags = sample.point[0].flags;
      g_move_events++;

      if (g_state == LV_INDEV_STATE_RELEASED)
        {
          g_click_events++;
        }

      g_state = LV_INDEV_STATE_PRESSED;
      g_last_press_ms = now;
    }
  else if (g_state == LV_INDEV_STATE_PRESSED &&
           now - g_last_press_ms > RELEASE_TIMEOUT_MS)
    {
      g_state = LV_INDEV_STATE_RELEASED;
    }

  data->point.x = g_x;
  data->point.y = g_y;
  data->state = g_state;
}

static void touchtest_update_info(lv_timer_t *timer)
{
  lv_label_set_text_fmt(g_info_label,
                        "state:%s  x:%d  y:%d\nmoves:%d  clicks:%d"
                        "  flags:%02x",
                        g_state == LV_INDEV_STATE_PRESSED ? "DOWN" : "UP",
                        g_x, g_y, g_move_events, g_click_events,
                        g_last_flags);
}

static void touchtest_button_event(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);
  lv_obj_t *label = lv_event_get_user_data(e);

  if (code == LV_EVENT_CLICKED)
    {
      static int clicks;

      clicks++;
      lv_label_set_text_fmt(label, "CLICKED: %d", clicks);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  lv_indev_t *indev;
  lv_obj_t *btn;
  lv_obj_t *label;
  lv_obj_t *slider;

  lv_init();

  lv_nuttx_dsc_init(&info);
  info.input_path = NULL;        /* input is wired manually below */
  lv_nuttx_init(&info, &result);
  if (result.disp == NULL)
    {
      printf("touchtest: no display\n");
      return 1;
    }

  g_fd = open(TOUCHTEST_DEV, O_RDONLY);
  if (g_fd < 0)
    {
      printf("touchtest: open %s failed\n", TOUCHTEST_DEV);
      return 1;
    }

  indev = lv_indev_create();
  lv_indev_set_type(indev, LV_INDEV_TYPE_POINTER);
  lv_indev_set_read_cb(indev, touchtest_read_cb);
  lv_indev_set_display(indev, result.disp);
  lv_indev_set_mode(indev, LV_INDEV_MODE_TIMER);

  /* Live touch diagnostics at the top */

  g_info_label = lv_label_create(lv_screen_active());
  lv_obj_set_width(g_info_label, lv_display_get_horizontal_resolution(
                     lv_display_get_default()) - 40);
  lv_obj_align(g_info_label, LV_ALIGN_TOP_MID, 0, 40);
  lv_label_set_text(g_info_label, "touchtest: touch the screen");
  lv_obj_set_style_text_color(g_info_label, lv_palette_main(
                                LV_PALETTE_BLUE), 0);

  /* Big button to test clicks */

  btn = lv_button_create(lv_screen_active());
  lv_obj_set_size(btn, 500, 260);
  lv_obj_align(btn, LV_ALIGN_CENTER, 0, -100);

  label = lv_label_create(btn);
  lv_label_set_text(label, "TAP ME");
  lv_obj_center(label);
  lv_obj_add_event_cb(btn, touchtest_button_event, LV_EVENT_ALL, label);

  /* Slider to test drags */

  slider = lv_slider_create(lv_screen_active());
  lv_obj_set_width(slider, 600);
  lv_obj_align(slider, LV_ALIGN_CENTER, 0, 150);

  lv_timer_create(touchtest_update_info, 200, NULL);

  while (1)
    {
      uint32_t idle = lv_timer_handler();

      usleep((idle ? idle : 1) * 1000);
    }

  return 0;
}
